#include <iostream>
using namespace std;
int main() {
    int n, m;
    cin >> n >> m;
    int a[50][50];
    for (int i = 0; i < n; i++)
        for (int j = 0; j < m; j++)
            cin >> a[i][j];

    int top = 0, bottom = n - 1, left = 0, right = m - 1;
    bool first = true;
    while (top <= bottom && left <= right) {
        // right
        for (int j = left; j <= right; j++) {
            if (!first) cout << " ";
            cout << a[top][j];
            first = false;
        }
        top++;
        // down
        for (int i = top; i <= bottom; i++) {
            cout << " " << a[i][right];
        }
        right--;
        // left
        if (top <= bottom) {
            for (int j = right; j >= left; j--) {
                cout << " " << a[bottom][j];
            }
            bottom--;
        }
        // up
        if (left <= right) {
            for (int i = bottom; i >= top; i--) {
                cout << " " << a[i][left];
            }
            left++;
        }
    }
    cout << endl;
    return 0;
}

