#include <iostream>
#include <string>
using namespace std;

struct Player {
    string name;
    int score;
};

void swapPlayer(Player &x, Player &y) {
    Player tmp = x;
    x = y;
    y = tmp;
}

int main() {
    int n;
    cin >> n;
    Player players[100];
    for (int i = 0; i < n; i++) {
        cin >> players[i].name >> players[i].score;
    }
    // Bubble sort descending: swap only when strictly <
    for (int i = 0; i < n - 1; i++) {
        for (int j = 0; j < n - 1 - i; j++) {
            if (players[j].score < players[j + 1].score) {
                swapPlayer(players[j], players[j + 1]);
            }
        }
    }
    for (int i = 0; i < n; i++) {
        cout << players[i].name << " " << players[i].score << endl;
    }
    return 0;
}

